SELECT * FROM (
    SELECT 
    FROM HR_EMPLOYEE E
    WHERE E.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}

      AND (
          UPPER(E.EMPID) LIKE '%' || UPPER(#{keyword, jdbcType=VARCHAR}) || '%'
          OR CONVERTTOUNSIGN(UPPER(E.LOCAL_NAME)) LIKE '%' || CONVERTTOUNSIGN(UPPER(#{keyword, jdbcType=VARCHAR})) || '%'
      )

    ORDER BY E.EMPID
) WHERE ROWNUM <= 100

SELECT 
FROM HR_EMPLOYEE E
WHERE E.PERSON_ID = #{personId, jdbcType=VARCHAR}

